previewCss:
.darma-loader-darma-b16-launch-countdown { --accent: var(--loader-color, #1d4ed8); --accent-2: var(--loader-secondary-color, #f97316); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .46); position: relative; }
.darma-loader-darma-b16-launch-countdown .darma-loader-darma-b16-launch-countdown__row { position: absolute; left: 0; right: 0; top: 0; height: 58%; display: flex; gap: 3%; align-items: stretch; }
.darma-loader-darma-b16-launch-countdown span { flex: 1; border-radius: 5px; background: color-mix(in srgb, var(--accent) 22%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent); animation: darma-loader-darma-b16-launch-countdown-count-tick calc(var(--loader-speed, 1s) * 3) steps(1, end) infinite; }
.darma-loader-darma-b16-launch-countdown span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b16-launch-countdown span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b16-launch-countdown span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b16-launch-countdown span:nth-of-type(5) { animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
.darma-loader-darma-b16-launch-countdown .darma-loader-darma-b16-launch-countdown__flare { position: absolute; left: 39%; bottom: 2%; width: 22%; height: 36%; transform-origin: 50% 0; border-radius: 50% 50% 40% 40%; background: radial-gradient(ellipse at 50% 15%, var(--accent-2), transparent 72%); opacity: 0; animation: darma-loader-darma-b16-launch-countdown-count-ignite calc(var(--loader-speed, 1s) * 3) ease-out infinite; }
@keyframes darma-loader-darma-b16-launch-countdown-count-tick { 0%, 12% { background: color-mix(in srgb, var(--accent) 20%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 40%, transparent); } 13%, 66% { background: var(--accent-2); box-shadow: inset 0 0 0 2px var(--accent-2); } 67%, 100% { background: color-mix(in srgb, var(--accent) 20%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 40%, transparent); } }
@keyframes darma-loader-darma-b16-launch-countdown-count-ignite { 0%, 66% { opacity: 0; transform: scaleY(.3); } 74% { opacity: 1; transform: scaleY(1.1); } 92%, 100% { opacity: 0; transform: scaleY(.3); } }

